#include <iostream>
#include <iomanip>
#include <cstddef>

int main() {
    // 1. Initializer list with exact size
    int values[5] = {32, 27, 64, 18, 95};

    // 2. Partial initialization (remaining elements zeroed)
    int partial[5] = {10, 20};

    // 3. Deduced array size
    int deduced[] = {100, 200, 300};

    std::cout << "Element" << std::setw(13) << "Value" << "\n";
    for (std::size_t i = 0; i < 5; ++i) {
        std::cout << std::setw(7) << i << std::setw(13) << values[i] << "\n";
    }

    std::cout << "\nPartial zero-filled elements 2 to 4:\n";
    for (std::size_t i = 0; i < 5; ++i) {
        std::cout << "partial[" << i << "] = " << partial[i] << "\n";
    }

    std::cout << "\nDeduced array size: " << sizeof(deduced) / sizeof(deduced[0]) << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cstddef>

// Modern C++17 compile-time constants replace legacy #define
constexpr std::size_t EVEN_SIZE = 5;
constexpr std::size_t DATA_SIZE = 12;

int main() {
    // 1. Initializing array elements with calculations (Fig. 6.5)
    int s[EVEN_SIZE];
    for (std::size_t j = 0; j < EVEN_SIZE; ++j) {
        s[j] = 2 + 2 * static_cast<int>(j);
    }

    std::cout << "Element" << std::setw(13) << "Value" << "\n";
    for (std::size_t j = 0; j < EVEN_SIZE; ++j) {
        std::cout << std::setw(7) << j << std::setw(13) << s[j] << "\n";
    }

    // 2. Summing elements of an array (Fig. 6.6)
    int a[DATA_SIZE] = {1, 3, 5, 4, 7, 2, 99, 16, 45, 67, 89, 45};
    int total = 0;

    for (std::size_t i = 0; i < DATA_SIZE; ++i) {
        total += a[i];
    }

    std::cout << "\nTotal of array element values is " << total << "\n";
    return 0;
}
